32	// exception is the thing that looks unusual.
33	func readyPlacement(id, cell, slug, jurisdiction string) coreapi.RepoPlacement {
34		return coreapi.RepoPlacement{ID: id, Cell: cell, ClusterSlug: slug, Jurisdiction: jurisdiction, Mirror: true, Status: coreapi.RepoPlacementStatusReady}
