37	func TestGroupReposByCell(t *testing.T) {
38		t.Parallel()
39		repos := []coreapi.RepoIndexEntry{
40			{ID: "01B", Cell: usEastCell, ClusterSlug: testClusterSlugUS, Jurisdiction: "us"},
41			{ID: "01C", Cell: "AWS-US-EAST-2", ClusterSlug: testClusterSlugUS, Jurisdiction: "US"}, // case-folds into same group
42			{ID: testPlacementA, Cell: euWestCell, ClusterSlug: testClusterSlugEU, Jurisdiction: "eu"},
43			{ID: "", Cell: euWestCell}, // no ID → skipped
44			// Blank cell in different jurisdictions must NOT collapse into one
45			// group — each routes via its own jurisdiction fallback.
46			{ID: "01D", Jurisdiction: "eu"},
47			{ID: "01E", Jurisdiction: "us"},
48		}
49		cells, _ := groupReposByCell(repos)
50		if len(cells) != 4 {
51			t.Fatalf("groups = %d, want 4: %+v", len(cells), cells)
52		}
53		// Deterministic order by cell name, jurisdiction tiebreak:
54		// ""/eu < ""/us < aws-eu-west-1 < aws-us-east-2.
55		order := []struct{ cell, jurisdiction string }{
56			{"", "eu"}, {"", "us"}, {euWestCell, "eu"}, {usEastCell, "us"},
57		}
58		for i, want := range order {
59			if cells[i].cell != want.cell || cells[i].jurisdiction != want.jurisdiction {
60				t.Fatalf("group[%d] = %q/%q, want %q/%q", i, cells[i].cell, cells[i].jurisdiction, want.cell, want.jurisdiction)
61			}
