64			t.Fatalf("blank-cell eu repoIDs = %q, want 01D", got)
65		}
66		us := cells[3]
67		if got := strings.Join(us.repoIDs, ","); got != "01B,01C" {
68			t.Fatalf("us repoIDs = %q, want 01B,01C", got)
69		}
70		if us.clusterSlug != testClusterSlugUS || us.jurisdiction != "us" {
71			t.Fatalf("us group coordinates = %+v, want us-prod/us", us)
